public extension NexusTheme {
    /// Every built-in theme, in the same order the terminal lists them.
    static let all: [NexusTheme] = [
        .nexusNoir,
        .paperNexus,
        .solarFlare,
        .glacier,
        .contrastMax,
        .synthwaveGrid,
        .neon,
        .midnight,
        .vampire,
        .retroAmber,
        .pastel,
        .frost,
        .matrix,
        .vivid,
        .rose,
        .forest,
    ]

    static let defaultThemeId = "nexus-noir"

    static func named(_ id: String) -> NexusTheme? {
        all.first { $0.id == id }
    }
}
